patch:
diff --git a/repro/no-lonely-if-nested-else.js b/repro/no-lonely-if-nested-else.js
new file mode 100644
index 0000000..bc29252
--- /dev/null
+++ b/repro/no-lonely-if-nested-else.js
@@ -0,0 +1,46 @@
+"use strict";
+
+/*
+ * Reproduction: no-lonely-if autofix changes which `if` an `else` binds to
+ * when the lonely `if` sits in an `else` block of an `if` that is itself the
+ * brace-less consequent of an outer `if`.
+ */
+
+const assert = require("node:assert");
+const { Linter } = require(process.env.ESLINT_PATH || "../lib/api");
+
+const code = [
+    "/* eslint no-lonely-if: \"error\" */",
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');"
+].join("\n");
+
+const linter = new Linter();
+
+console.log("ESLint", Linter.version);
+console.log("Messages:", linter.verify(code, {}).map(m => `${m.line}:${m.column} ${m.ruleId}: ${m.message}`));
+
+const { output, fixed } = linter.verifyAndFix(code, {});
+
+console.log("\n--- input ---\n" + code);
+console.log("\n--- fixed output ---\n" + output);
+
+function runs(src) {
+    try {
+        new Function(src)(); // eslint-disable-line no-new-func -- evaluate snippet
+        return "completes normally";
+    } catch (err) {
+        return `throws: ${err.message}`;
+    }
+}
+
+const before = runs(code);
+const after = runs(output);
+
+console.log("\nInput at runtime: ", before);
+console.log("Output at runtime:", after);
+
+console.log("Fix applied:", fixed);
+assert.strictEqual(after, before, "BUG: autofix changed program behavior (outer `else` now binds to the inner `if`)");
